<?php

namespace Plugin\SubContent43\Repository;

use Eccube\Repository\AbstractRepository;
use Plugin\SubContent43\Entity\Config;
use Doctrine\Persistence\ManagerRegistry; 
use Plugin\SubContent43\Service\ScService;
use Doctrine\ORM\NoResultException;




/**
 * ConfigRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class ConfigRepository extends AbstractRepository
{
    /**
     * ConfigRepository constructor.
     *
     * @param ManagerRegistry $registry
     */
    public function __construct(ManagerRegistry $registry)
    {
        parent::__construct($registry, Config::class);
    }

    /**
     * 新規登録
     *
     * @return Plugin\SubContent43\Entity\Config
     */
    public function New()
    {
        return  new Config();
    }

    /**
     * ホルダーのセレクト配列を取得する
     *
     * @return array() 
     */
    public function GetSelectHolder(){

        $Configs = $this->findBy([],['id'=>'ASC']);
        
        $Re[ trans('SubContent_Select_Message_2')]='';
        if (count($Configs)<1){return $Re;}

       
        //$HolderJs=[];
        foreach ($Configs as $Config){
               if($Config->getId() != $Config->getJoinId()){continue;} 
               $Re[$Config->getHolder()]=$Config->getId();
        }

        return $Re;

    }

    public function GetConfig(string $Holder){
         $Configs = $this->findBy(['holder'=>$Holder]);

        return $Configs[0] ?? null;

    }
    public function CheckConfig($Holder,$Id){

        $qb = $this->createQueryBuilder('c')
                ->where('c.holder = :Holder')
                ->setParameter('Holder', $Holder);

        if ($Id){
            $qb->andWhere('c.id != :Id')
               ->setParameter('Id', $Id);            
        }
       
        try{
      
            return  $qb->getQuery()
                       ->getSingleResult();

        } catch (NoResultException $e) {
            return false;
                                  
        }

    }
    public function GetJoinId($id){

        $qb = $this->createQueryBuilder('c')
                   ->where('c.id = c.join_id')
                   ->andWhere('c.id != :ID')
                   ->setParameter('ID', $id);
        $Datas = $qb->getQuery()->getResult();

        if (!$Datas) {return [];}

        $Re = [];
        foreach ($Datas as $Data){
            $Re[$Data->getHolder()] = $Data->getId();
        }

        return $Re;

    }
    public function GetRoot(){

        $Configs = $this->findAll();
        $Re=[];
        foreach($Configs as $Config){
            $kigo = $Config->GetRequirements() ? ScService::Kigo : '';
            $Re['/'.$Config->getHolder()] = $Config->getHolder() . $kigo;
        }
        return $Re;

    }



}
